static void Main(string[] args)
{
    int[] nums = { 1, -2, 3, 0, -4, 5 };
    var posNums = nums.Where(n => n > 0)
                      .Select(r => r * 2)
                      .OrderByDescending(r => r);

    foreach (int i in posNums) Console.Write(i + " ");
}

